package proto

// OpEnvelopeDomain is the signing domain for OpEnvelope (PROTOCOL.md §4.1).
const OpEnvelopeDomain = "op"

// OpEnvelope mirrors PROTOCOL.md §4.1 field-for-field. No test vector governs it yet (op.json is
// listed as "planned" in testvectors/README.md but not yet generated by core) - this is the
// relay's own best-effort reading of the spec table, same discipline as DeviceRevoke.
//
// The relay never decrypts Ct (it has no epochKey - see package doc and CLAUDE.md's "relay never
// decrypts content" rule) and never computes the AEAD associated data (fields 0..7 without Ct) -
// that's purely a client-side concern for producing/consuming Ct. The relay only verifies the
// *outer* signature (domain "op", over fields 0..8 i.e. everything except Sig) and stores Ct
// opaquely.
type OpEnvelope struct {
	V       uint64 `cbor:"0,keyasint"`
	Room    []byte `cbor:"1,keyasint"`
	Epoch   uint64 `cbor:"2,keyasint"`
	Author  []byte `cbor:"3,keyasint"`
	Device  []byte `cbor:"4,keyasint"`
	Seq     uint64 `cbor:"5,keyasint"`
	Lamport uint64 `cbor:"6,keyasint"`
	Nonce   []byte `cbor:"7,keyasint"`
	Ct      []byte `cbor:"8,keyasint"`
	Sig     []byte `cbor:"9,keyasint,omitempty"`
}

// DecodeOpEnvelope decodes and rejects anything that is not canonical CBOR (PROTOCOL.md §1).
func DecodeOpEnvelope(data []byte) (*OpEnvelope, error) {
	var e OpEnvelope
	if err := DecodeCanonicalInto(data, &e); err != nil {
		return nil, err
	}
	return &e, nil
}

func (e OpEnvelope) unsignedCbor() ([]byte, error) {
	e.Sig = nil
	return EncodeCanonical(e)
}

// FullCbor is all fields 0..9 incl. Sig - what OpID is computed over and what travels on the wire.
func (e OpEnvelope) FullCbor() ([]byte, error) {
	return EncodeCanonical(e)
}

// OpID is `BLAKE2b(CBOR(full envelope))` (PROTOCOL.md §4.1).
func (e OpEnvelope) OpID() ([]byte, error) {
	full, err := e.FullCbor()
	if err != nil {
		return nil, err
	}
	return Blake2b256(full), nil
}

// Verify is self-contained crypto/structural validity only: known version and a valid Ed25519
// signature by Device under domain "op". It does NOT check that Device actually belongs to
// Author, is unrevoked, that Author is a current room member, or that Epoch matches the room's
// current epoch - those need store/membership-state lookups this package has no access to (see
// package api's postOps).
func (e OpEnvelope) Verify() bool {
	if e.Sig == nil || e.V != 1 {
		return false
	}
	unsigned, err := e.unsignedCbor()
	if err != nil {
		return false
	}
	return Ed25519Verify(e.Device, SigningInput(OpEnvelopeDomain, unsigned), e.Sig)
}
